import os
import sys


def main():
    total = 0
    with open(os.path.join("data", "nums.txt"), "r", encoding="utf-8") as f:
        for line in f:
            s = line.strip()
            if not s:
                continue
            total += int(s)

    os.makedirs("out", exist_ok=True)
    with open(os.path.join("out", "answer.txt"), "w", encoding="utf-8", newline="\n") as f:
        f.write(str(total) + "\n")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as e:
        sys.stderr.write(f"error: {e}\n")
        sys.exit(1)
